# Fused RMSNorm kernel
rmsnorm_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

template<typename T>
__global__ void rmsnorm_kernel(
    const T* __restrict__ input,
    const float* __restrict__ weight,
    T* __restrict__ output,
    int hidden_size,
    int num_elements,
    float eps
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < num_elements; i += stride) {
        // Compute variance for this row
        float sum_sq = 0.0f;
        int base = (i / hidden_size) * hidden_size;
        for (int j = 0; j < hidden_size; j++) {
            float val = static_cast<float>(input[base + j]);
            sum_sq += val * val;
        }
        float variance = sum_sq / hidden_size;
        float inv_std = rsqrtf(variance + eps);

        // Apply normalization
        output[i] = static_cast<T>(static_cast<float>(input[i]) * inv_std * weight[i % hidden_size]);
    }
}

torch::Tensor rmsnorm_hip(torch::Tensor input, torch::Tensor weight, float eps) {
    auto num_elements = input.numel();
    auto hidden_size = input.size(-1);
    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    rmsnorm_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        hidden_size,
        num_elements,
        eps
    );

    return output;
}
"""

# Fused RoPE kernel
rope_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void apply_rotary_emb_kernel(
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ q_out,
    float* __restrict__ k_out,
    int batch_size,
    int num_heads,
    int seq_len,
    int head_dim
) {
    int b = blockIdx.x;
    int h = blockIdx.y;
    int t = threadIdx.x;

    if (b >= batch_size || h >= num_heads || t >= seq_len) return;

    int q_base = ((b * num_heads + h) * seq_len + t) * head_dim;
    int k_base = ((b * num_heads + h) * seq_len + t) * head_dim;

    int cos_base = t * head_dim;

    for (int d = 0; d < head_dim / 2; d++) {
        int d_idx = d;
        int half_dim = head_dim / 2;

        float q_real = q[q_base + d_idx];
        float q_imag = q[q_base + d_idx + half_dim];
        float k_real = k[k_base + d_idx];
        float k_imag = k[k_base + d_idx + half_dim];

        float c = cos[cos_base + d_idx];
        float s = sin[cos_base + d_idx];

        // Apply rotation: (a + ib) * (c + is) = (ac - bs) + i(as + bc)
        q_out[q_base + d_idx] = q_real * c - q_imag * s;
        q_out[q_base + d_idx + half_dim] = q_real * s + q_imag * c;
        k_out[k_base + d_idx] = k_real * c - k_imag * s;
        k_out[k_base + d_idx + half_dim] = k_real * s + k_imag * c;
    }
}

std::vector<torch::Tensor> apply_rotary_emb_hip(
    torch::Tensor q, torch::Tensor k, torch::Tensor cos, torch::Tensor sin
) {
    auto batch_size = q.size(0);
    auto num_heads = q.size(1);
    auto seq_len = q.size(2);
    auto head_dim = q.size(3);

    auto q_out = torch::empty_like(q);
    auto k_out = torch::empty_like(k);

    dim3 grid(batch_size, num_heads);
    int block_size = std::min(256, seq_len);

    apply_rotary_emb_kernel<<<grid, block_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        q_out.data_ptr<float>(),
        k_out.data_ptr<float>(),
        batch_size,
        num_heads,
        seq_len,
        head_dim
    );

    return {q_out, k_out};
}
"""

# Fused attention kernel with masked softmax
attention_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

__global__ void fused_attention_kernel(
    const float* __restrict__ query,
    const float* __restrict__ key,
    const float* __restrict__ value,
    float* __restrict__ output,
    int batch_size,
    int num_heads,
    int seq_len,
    int head_dim,
    float softmax_scale
) {
    int b = blockIdx.x;
    int h = blockIdx.y;

    if (b >= batch_size || h >= num_heads) return;

    int out_base = ((b * num_heads + h) * seq_len) * head_dim;

    // Process each query position
    for (int t = threadIdx.x; t < seq_len; t += blockDim.x) {
        int q_base = ((b * num_heads + h) * seq_len + t) * head_dim;

        // Compute attention scores for this query position
        float scores[2048];  // Max seq_len

        for (int i = 0; i < seq_len; i++) {
            int k_base = ((b * num_heads + h) * seq_len + i) * head_dim;

            // Dot product
            float dot = 0.0f;
            for (int d = 0; d < head_dim; d++) {
                dot += query[q_base + d] * key[k_base + d];
            }

            // Apply causal mask (only pay attention to positions <= current)
            scores[i] = (i <= t) ? dot * softmax_scale : -1e10f;
        }

        // Compute softmax
        float max_score = -1e10f;
        for (int i = 0; i <= t; i++) {
            max_score = fmaxf(max_score, scores[i]);
        }

        float sum = 0.0f;
        for (int i = 0; i <= t; i++) {
            scores[i] = expf(scores[i] - max_score);
            sum += scores[i];
        }

        // Normalize
        for (int i = 0; i <= t; i++) {
            scores[i] /= sum;
        }

        // Apply attention to value
        for (int d = 0; d < head_dim; d++) {
            float accum = 0.0f;
            for (int i = 0; i <= t; i++) {
                int v_base = ((b * num_heads + h) * seq_len + i) * head_dim;
                accum += scores[i] * value[v_base + d];
            }
            output[out_base + t * head_dim + d] = accum;
        }
    }
}

torch::Tensor fused_attention_hip(
    torch::Tensor query, torch::Tensor key, torch::Tensor value, float softmax_scale
) {
    auto batch_size = query.size(0);
    auto num_heads = query.size(1);
    auto seq_len = query.size(2);
    auto head_dim = query.size(3);

    auto output = torch::empty({batch_size, num_heads, seq_len, head_dim}, 
                               query.options());

    dim3 grid(batch_size, num_heads);

    // Use enough threads to cover seq_len
    int block_size = std::min(256, seq_len);

    fused_attention_kernel<<<grid, block_size>>>(
        query.data_ptr<float>(),
        key.data_ptr<float>(),
        value.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_heads,
        seq_len,
        head_dim,
        softmax_scale
    );

    return output;
}
"""

rmsnorm = load_inline(
    name="rmsnorm",
