class ModelNew(nn.Module):
    """
    Optimized FP8 Matrix Multiplication with custom HIP kernels.

    Optimizations:
    1. Custom amax computation kernel with efficient parallel reduction
    2. Custom quantization kernel with optimized memory access
    3. Maintains tensor core GEMM from baseline
    """
    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        self.quantize_fused = quantize_fused

        # FP8 format specifications
        if use_e4m3:
            self.fp8_dtype = torch.float8_e4m3fn
            self.fp8_max = 448.0
        else:
            self.fp8_dtype = torch.float8_e5m2
            self.fp8_max = 57344.0

        self.weight = nn.Parameter(torch.randn(K, N) * 0.02)

    def compute_scale(self, x: torch.Tensor) -> torch.Tensor:
        """Compute per-tensor scale for FP8 quantization using custom HIP kernel."""
        amax = self.quantize_fused.compute_amax_hip(x)
        scale = self.fp8_max / amax.clamp(min=1e-12)
        return scale

    def quantize_to_fp8(self, x: torch.Tensor, scale: torch.Tensor) -> torch.Tensor:
        """Quantize FP16 tensor to FP8 using custom HIP kernel."""
        x_fp8 = torch.empty_like(x, dtype=self.fp8_dtype)

        # Create temporary half tensor for the kernel output
        x_fp8_half = torch.empty_like(x, dtype=torch.float16)
        x_fp8_half = self.quantize_fused.quantize_to_fp8_hip(x, scale, self.fp8_max, x_fp8_half)

        # Convert to actual FP8 dtype
        return x_fp8_half.to(self.fp8_dtype)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        FP8 matmul using tensor cores: x @ weight
        """
        input_dtype = x.dtype
        batch_size = x.shape[0]
        seq_len = x.shape[1]

        x_2d = x.view(-1, self.K)

        x_scale = self.compute_scale(x_2d)
        w_scale = self.compute_scale(self.weight)

        x_fp8 = self.quantize_to_fp8(x_2d, x_scale)

        w_t = self.weight.t().contiguous()
        w_fp8 = self.quantize_to_fp8(w_t, w_scale)

        x_scale_inv = (1.0 / x_scale).to(torch.float32)
        w_scale_inv = (1.0 / w_scale).to(torch.float32)

        out = torch._scaled_mm(
            x_fp8,
            w_fp8.t(),
            scale_a=x_scale_inv,
            scale_b=w_scale_inv,
            out_dtype=input_dtype,
        )

        return out.view(batch_size, seq_len, self.N)


