)


class ModelNew(nn.Module):
    """
    INT4 Weight-Only Quantized Linear Layer with Symmetric Quantization - Optimized.

    Optimizations:
    1. Fused kernel combines unpacking, dequantization, and GEMM in one pass
    2. Avoids materializing full FP16 weight matrix
    3. Uses shared memory tiling for memory efficiency
    4. Processes multiple outputs per thread for better utilization
    """
    def __init__(self, K: int, N: int, group_size: int = 128):
        super().__init__()
        self.K = K
        self.N = N
        self.group_size = group_size
        self.num_groups = K // group_size

        assert K % group_size == 0, "K must be divisible by group_size"
        assert K % 2 == 0, "K must be even for INT4 packing"

        # Packed INT4 weights
        self.register_buffer(
            "weight_packed",
            torch.randint(0, 256, (N, K // 2), dtype=torch.uint8)
        )

        # Per-group scales
        self.register_buffer(
            "scales",
            torch.randn(N, self.num_groups, dtype=torch.float16).abs() * 0.1
        )

        # Load the custom kernel
        self.int4_gemm_kernel = int4_gemm

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Optimized INT4 quantized linear using fused kernel.

        Input x: (batch, seq_len, K) in FP16
        Output: (batch, seq_len, N) in FP16
        """
        batch_size, seq_len, _ = x.shape

        # Reshape to 2D for matmul
        x_2d = x.view(-1, self.K)  # (batch*seq, K)
        M = x_2d.size(0)

        # Keep weights in (N, K//2) format for indexing
        w_packed = self.weight_packed
        scales = self.scales

        # Call fused kernel
        out = self.int4_gemm_kernel.int4_gemm_fused_hip(
            x_2d, w_packed, scales, self.K, self.N, self.group_size
        )

        # Reshape back to 3D
        return out.view(batch_size, seq_len, self.N)


