moe_gated_gemm_source = """
#include <torch/extension.h>

#define BLOCK_SIZE 256

__device__ __forceinline__ float silu(float x) {
    return x * (1.0f / (1.0f + expf(-x)));
}

__global__ void moe_gated_gemm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gate_weights,
    const float* __restrict__ up_weights,
    const float* __restrict__ down_weights,
    float* __restrict__ output,
    int hidden_size,
    int intermediate_size,
    int num_tokens
) {
    int token_idx = blockIdx.x;
    if (token_idx >= num_tokens) return;

    int tid = threadIdx.x;

    for (int out_idx = tid; out_idx < hidden_size; out_idx += blockDim.x) {
        float down_sum = 0.0f;

        for (int k = 0; k < intermediate_size; k++) {
            float gate_val = 0.0f;
            float up_val = 0.0f;

            for (int j = 0; j < hidden_size; j += 4) {
                for (int u = 0; u < 4 && (j + u) < hidden_size; u++) {
                    float x_val = x[token_idx * hidden_size + j + u];
                    gate_val += x_val * gate_weights[k * hidden_size + j + u];
                    up_val += x_val * up_weights[k * hidden_size + j + u];
                }
            }

            gate_val = silu(gate_val);
            down_sum += gate_val * up_val * down_weights[out_idx * intermediate_size + k];
        }

        output[token_idx * hidden_size + out_idx] = down_sum;
    }
}

torch::Tensor moe_gated_gemm_hip(
    torch::Tensor x,
    torch::Tensor gate_weights,
    torch::Tensor up_weights,
    torch::Tensor down_weights
) {
    int num_tokens = x.size(0);
    int hidden_size = x.size(1);
    int intermediate_size = gate_weights.size(0);

    auto output = torch::zeros_like(x);

    moe_gated_gemm_kernel<<<num_tokens, BLOCK_SIZE>>>(
        x.data_ptr<float>(),
        gate_weights.data_ptr<float>(),
        up_weights.data_ptr<float>(),
        down_weights.data_ptr<float>(),
        output.data_ptr<float>(),
        hidden_size,
        intermediate_size,
        num_tokens
    );

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("moe_gated_gemm_hip", &moe_gated_gemm_hip, "MoE Gated GEMM kernel");
}
"""

moe_gated_gemm = load_inline(
    name="moe_gated_gemm",
    cpp_sources=moe_gated_gemm_source,
    functions=["moe_gated_gemm_hip"],
    extra_cuda_cflags=["-O3"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized MoE Expert with fused gated GEMM kernel.
    """
    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        num_experts: int,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        self.gate_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(num_experts, hidden_size, intermediate_size) * 0.02
        )

        self.moe_gated_gemm = moe_gated_gemm

    def forward(
        self,
        x: torch.Tensor,
        expert_indices: torch.Tensor,
        expert_weights: torch.Tensor,
    ) -> torch.Tensor:
        batch, seq_len, _ = x.shape
        top_k = expert_indices.shape[-1]

        x_flat = x.view(-1, self.hidden_size)
        num_tokens = x_flat.shape[0]

        output = torch.zeros(num_tokens, self.hidden_size, device=x.device, dtype=x.dtype)

        for expert_idx in range(self.num_experts):
            expert_mask = (expert_indices == expert_idx)

            if not expert_mask.any():
                continue

            batch_idx, seq_idx, slot_idx = torch.where(expert_mask)
            token_indices = batch_idx * seq_len + seq_idx
            weights = expert_weights[batch_idx, seq_idx, slot_idx]

            expert_input = x_flat[token_indices]

            expert_output = self.moe_gated_gemm.moe_gated_gemm_hip(
                expert_input,
                self.gate_proj[expert_idx],
                self.up_proj[expert_idx],
                self.down_proj[expert_idx]
            )

            output.index_add_(0, token_indices, expert_output * weights.unsqueeze(-1))

        return output.view(batch, seq_len, self.hidden_size)

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

int4_gemm_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

__global__ void int4_gemm_fused_kernel(
    const half* __restrict__ x,           // (M, K)
    const uint8_t* __restrict__ w_packed, // (N, K//2) packed INT4 weights
    const half* __restrict__ scales,      // (N, num_groups) per-group scales
    half* __restrict__ output,            // (M, N)
    int M, int N, int K, int group_size
) {
    const int row = blockIdx.y * blockDim.y + threadIdx.y;
    const int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= M || col >= N) return;

    // Accumulator
    float acc = 0.0f;
    int num_groups = K / group_size;

    for (int k = 0; k < K; k++) {
        // Load input
        half x_val = x[row * K + k];
        float x_f = __half2float(x_val);

        // Get packed weight index
        // w_packed is (N, K//2) stored row-major
        int k_pair = k / 2;  // Which byte in K dimension (0 to K/2-1)
        // Flat index: row=n, col=k_pair
        int packed_idx = col * (K / 2) + k_pair;

        uint8_t packed_byte = w_packed[packed_idx];

        // Unpack INT4: low nibble is k when even, high nibble when odd
        int w_int;
        if (k % 2 == 0) {
            w_int = packed_byte & 0x0F;  // Low nibble
        } else {
            w_int = (packed_byte >> 4) & 0x0F;  // High nibble
        }

        // Get scale for this group
        int group_idx = k / group_size;
        flat scale_idx = col * num_groups + group_idx;
        half scale_h = scales[scale_idx];
        float scale_f = __half2float(scale_h);

        // Dequantize and accumulate
        float w_deq = scale_f * ((float)w_int - 8.0f);
        acc += x_f * w_deq;
    }

    output[row * N + col] = __float2half(acc);
}

torch::Tensor int4_gemm_fused_hip(torch::Tensor x, torch::Tensor w_packed, torch::Tensor scales, int K, int N, int group_size) {
    auto M = x.size(0);
    auto output = torch::zeros({M, N}, x.options());

    dim3 block(32, 8);
    dim3 grid((N + 31) / 32, (M + 7) / 8);

    int4_gemm_fused_kernel<<<grid, block>>>(
        reinterpret_cast<half*>(x.data_ptr<c10::Half>()),
        w_packed.data_ptr<uint8_t>(),
        reinterpret_cast<half*>(scales.data_ptr<c10::Half>()),
        reinterpret_cast<half*>(output.data_ptr<c10::Half>()),
        M, N, K, group_size
    );

    return output;
}
"""

int4_gemm = load_inline(
