os.environ["CXX"] = "hipcc"

# Fused GQA attention kernel that avoids explicit KV head expansion
gqa_attention_hip_source = r"""
#include <hip/hip_runtime.h>
#include <math.h>
#include <cuda_fp16.h>

#define WARP_SIZE 32

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_xor(val, offset);
    }
    return val;
}

__global__ void gqa_attention_fused_kernel(
    const float* __restrict__ q,        // [batch, num_heads, seq_len, head_dim]
    const float* __restrict__ k,        // [batch, num_kv_heads, seq_len, head_dim]
    const float* __restrict__ v,        // [batch, num_kv_heads, seq_len, head_dim]
    float* __restrict__ output,         // [batch, num_heads, seq_len, head_dim]
    float softmax_scale,
    int batch_size,
    int num_heads,
    int num_kv_heads,
    int seq_len,
    int head_dim,
    int key_value_groups
) {
    // Each block handles one query head and one query position
    const int batch_idx = blockIdx.z;
    const int q_head_idx = blockIdx.y;
    const int q_pos = blockIdx.x;

    // Compute corresponding KV head (multiple query heads share same KV head)
    const int kv_head_idx = q_head_idx / key_value_groups;

    // Causal mask: only compute for positions <= q_pos
    const int kv_seq_len = min(q_pos + 1, seq_len);

    // Lane ID in warp
    const int lane_id = threadIdx.x;

    // Shared memory for attention weights
    extern __shared__ float s_mem[];
    float* w_sh = s_mem;

    // 1. Load query vector element
    float q_val = q[(batch_idx * num_heads + q_head_idx) * seq_len * head_dim + q_pos * head_dim + lane_id];

    // 2. Compute QK^T for each key position
    #pragma unroll
    for (int kv_pos = 0; kv_pos < kv_seq_len; kv_pos++) {
        float k_val = k[(batch_idx * num_kv_heads + kv_head_idx) * seq_len * head_dim + kv_pos * head_dim + lane_id];
        float sum_qk = q_val * k_val;

        // Warp reduction to get dot product
        sum_qk = warp_reduce_sum(sum_qk);

        // Store in shared memory (only lane 0 writes)
        if (lane_id == 0) {
            w_sh[kv_pos] = sum_qk * softmax_scale;
        }
    }

    __syncthreads();

    // 3. Softmax - compute max
    float my_max = -INFINITY;
    for (int i = lane_id; i < kv_seq_len; i += WARP_SIZE) {
        if (w_sh[i] > my_max) {
            my_max = w_sh[i];
        }
    }

    // Get global max
    float max_val = my_max;
    for (int offset = 16; offset > 0; offset /= 2) {
        max_val = fmaxf(max_val, __shfl_xor(max_val, offset));
    }
    max_val = __shfl(max_val, 0);

    // 4. Compute exp and sum
    float my_exp_sum = 0.0f;
    for (int i = lane_id; i < kv_seq_len; i += WARP_SIZE) {
        float exp_val = expf(w_sh[i] - max_val);
        w_sh[i] = exp_val;
        my_exp_sum += exp_val;
    }

    // Get global sum
    float exp_sum = my_exp_sum;
    for (int offset = 16; offset > 0; offset /= 2) {
        exp_sum += __shfl_xor(exp_sum, offset);
    }
    exp_sum = fmaxf(exp_sum, 1e-6f);

    // Normalize
    for (int i = lane_id; i < kv_seq_len; i += WARP_SIZE) {
        w_sh[i] = w_sh[i] / exp_sum;
    }

    __syncthreads();

    // 5. Compute weighted sum over V vectors
    float out_val = 0.0f;
    #pragma unroll
    for (int kv_pos = 0; kv_pos < kv_seq_len; kv_pos++) {
        float v_val = v[(batch_size * num_kv_heads + kv_head_idx) * seq_len * head_dim + kv_pos * head_dim + lane_id];
        out_val += w_sh[kv_pos] * v_val;
    }

    // 6. Write output
    output[(batch_size * num_heads + q_head_idx) * seq_len * head_dim + q_pos * head_dim + lane_id] = out_val;
}

torch::Tensor gqa_attention_forward(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    float softmax_scale,
    int key_value_groups
) {
    auto batch_size = q.size(0);
    auto num_heads = q.size(1);
    auto num_kv_heads = k.size(1);
    auto seq_len = q.size(2);
    auto head_dim = q.size(3);

    auto output = torch::empty_like(q);

    const int block_size = 32;  // One warp per block
    dim3 grid(seq_len, num_heads, batch_size);

    int shared_mem_size = seq_len * sizeof(float);  // Attention weights

    hipLaunchKernelGGL(
        (gqa_attention_fused_kernel),
        grid, dim3(block_size, 1, 1), shared_mem_size, 0,
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        output.data_ptr<float>(),
        softmax_scale,
        (int)batch_size,
        (int)num_heads,
        (int)num_kv_heads,
        (int)seq_len,
        (int)head_dim,
        (int)key_value_groups
    );

    return output;
}
"""

# Load the fused attention kernel
gqa_attention = load_inline(
    name="gqa_attention",
    cpp_sources=gqa_attention_hip_source,
    functions=["gqa_attention_forward"],
    extra_cflags=["-O3", "-ffast-math"],
    verbose=False,
)


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(q, k, cos, sin):
    """Apply rotary positional embeddings."""
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos().unsqueeze(0).unsqueeze(0), emb.sin().unsqueeze(0).unsqueeze(0)


class ModelNew(nn.Module):
    """
    Grouped Query Attention (GQA) - Optimized with Fused Kernel

    Optimizations:
    1. Replaced standard matmul attention with fused GQA kernel
    2. Avoids explicit KV head expansion (computes implicitly)
    3. Fuses dot product, softmax, and value aggregation in single kernel
    4. Reduces memory traffic by eliminating temporary KV expansion
    """

    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        max_position_embeddings: int = 4096,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.num_kv_heads = num_key_value_heads
        self.head_dim = head_dim
        self.num_key_value_groups = num_attention_heads // num_key_value_heads
        self.attention_dropout = attention_dropout
        self.softmax_scale = head_dim ** (-0.5)

        # Separate projections for Q, K, V
        self.q_proj = nn.Linear(hidden_size, num_attention_heads * head_dim, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.o_proj = nn.Linear(num_attention_heads * head_dim, hidden_size, bias=False)

        # Rotary embeddings
        self.rotary_emb = RotaryEmbedding(
            head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

        # Custom fused attention kernel
        self.gqa_kernel = gqa_attention

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        # Project Q, K, V
        query_states = self.q_proj(hidden_states)
        key_states = self.k_proj(hidden_states)
        value_states = self.v_proj(hidden_states)

        # Reshape for multi-head attention
        query_states = query_states.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2)
        key_states = key_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)
        value_states = value_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)

        # Apply rotary embeddings
        cos, sin = self.rotary_emb(value_states, seq_len=q_len)
        query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        # Compute attention with fused GQA kernel
        # This avoids explicit KV head expansion
        attn_output = self.gqa_kernel.gqa_attention_forward(
            query_states,
            key_states,
            value_states,
            self.softmax_scale,
            self.num_key_value_groups
        )

        # Apply dropout
        if self.attention_dropout > 0.0 and self.training:
            attn_output = F.dropout(attn_output, p=self.attention_dropout, training=True)

        # Reshape and output projection
        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.head_dim)
        attn_output = self.o_proj(attn_output)

        return attn_output

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Simplified HIP kernel without CUDA-specific headers
quantize_fused_source = """
#include <hip/hip_runtime.h>
#include <hip/amd_detail/amd_hip_fp16.h>

// Atomic max for float using HIP atomic operations
__device__ inline float atomicMaxFloat(float* addr, float value) {
    float old = *addr;
    float assumed;
    do {
        assumed = old;
        if (value <= assumed) break;
        __half* addr_half = (__half*)&value;
        __half* assumed_half = (__half*)&assumed;
        old = __atomic_compare_exchange_n((unsigned int*)addr, (unsigned int*)&assumed, __float_as_int(value), false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
    } while (true);
    return value;
}

// Optimized parallel reduction to compute amax
__global__ void compute_amax_kernel(
    const __half* __restrict__ input,
    float* __restrict__ amax_ptr,
    const int size)
{
    extern __shared__ float sdata[];

    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x * 2 + tid;
    int gridSize = blockDim.x * 2 * gridDim.x;

    float myMax = 0.0f;

    while (i < size) {
        __half val1 = input[i];
        float fval1 = __half2float(val1);
        if (fval1 < 0.0f) fval1 = -fval1;
        if (fval1 > myMax) myMax = fval1;

        if (i + blockDim.x < size) {
            __half val2 = input[i + blockDim.x];
            float fval2 = __half2float(val2);
            if (fval2 < 0.0f) fval2 = -fval2;
            if (fval2 > myMax) myMax = fval2;
        }
        i += gridSize;
    }

    sdata[tid] = myMax;
    __syncthreads();

    // Do reduction in shared mem
    if (blockDim.x >= 512) { if (tid < 256) { sdata[tid] = fmaxf(sdata[tid], sdata[tid + 256]); } __syncthreads(); }
    if (blockDim.x >= 256) { if (tid < 128) { sdata[tid] = fmaxf(sdata[tid], sdata[tid + 128]); } __syncthreads(); }
    if (blockDim.x >= 128) { if (tid < 64) { sdata[tid] = fmaxf(sdata[tid], sdata[tid + 64]); } __syncthreads(); }

    if (tid < 32) {
        if (blockDim.x >= 32) sdata[tid] = fmaxf(sdata[tid], sdata[tid + 32]);
        if (blockDim.x >= 16) sdata[tid] = fmaxf(sdata[tid], sdata[tid + 16]);
        if (blockDim.x >= 8)  sdata[tid] = fmaxf(sdata[tid], sdata[tid + 8]);
        if (blockDim.x >= 4)  sdata[tid] = fmaxf(sdata[tid], sdata[tid + 4]);
        if (blockDim.x >= 2)  sdata[tid] = fmaxf(sdata[tid], sdata[tid + 2]);
        if (blockDim.x >= 1)  sdata[tid] = fmaxf(sdata[tid], sdata[tid + 1]);
    }

    if (tid == 0) {
        atomicMaxFloat(amax_ptr, sdata[0]);
    }
}

// Kernel for quantization with pre-computed scale
__global__ void quantize_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const float scale,
    const float fp8_max_float,
    const int size)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= size) return;

    // Load input
    __half val = input[idx];

    // Scale to float
    float fval = __half2float(val);
    float scaled = fval * scale;

    // Clamp to fp8 range
    if (scaled > fp8_max_float) scaled = fp8_max_float;
    if (scaled < -fp8_max_float) scaled = -fp8_max_float;

    // Store as half (will be converted to FP8 by PyTorch)
    output[idx] = __float2half(scaled);
}

torch::Tensor compute_amax_hip(torch::Tensor input) {
    auto size = input.numel();
    torch::Tensor amax = torch::zeros({}, input.options().dtype(torch::kFloat32));

    const int block_size = 256;
    const int num_blocks = min((size + block_size - 1) / block_size, 65536);

    compute_amax_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        (const __half*)input.data_ptr(),
        amax.data_ptr<float>(),
        size
    );

    return amax;
}

torch::Tensor quantize_to_fp8_hip(torch::Tensor input, torch::Tensor scale_tensor, float fp8_max, torch::Tensor output_template) {
    auto size = input.numel();
    float scale = scale_tensor.item<float>();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    quantize_kernel<<<num_blocks, block_size>>>(
        (const __half*)input.data_ptr(),
        (__half*)output_template.data_ptr(),
        scale,
        fp8_max,
        size
    );

    return output_template;
}
"""

quantize_fused = load_inline(
    name="quantize_fused",
    cpp_sources=quantize_fused_source,
    functions=["compute_amax_hip", "quantize_to_fp8_hip"],
    verbose=True,
    extra_cuda_cflags=["-O3"],
)


class ModelNew(nn.Module):
    """Optimized FP8 Matrix Multiplication with custom HIP kernels."""
    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        self.quantize_fused = quantize_fused

        if use_e4m3:
            self.fp8_dtype = torch.float8_e4m3fn
            self.fp8_max = 448.0
        else:
            self.fp8_dtype = torch.float8_e5m2
            self.fp8_max = 57344.0

        self.weight = nn.Parameter(torch.randn(K, N) * 0.02)

    def compute_scale(self, x: torch.Tensor) -> torch.Tensor:
        amax = self.quantize_fused.compute_amax_hip(x)
        scale = self.fp8_max / amax.clamp(min=1e-12)
        return scale

    def quantize_to_fp8(self, x: torch.Tensor, scale: torch.Tensor) -> torch.Tensor:
        x_fp8_half = torch.empty_like(x, dtype=torch.float16)
        x_fp8_half = self.quantize_fused.quantize_to_fp8_hip(x, scale, self.fp8_max, x_fp8_half)
        return x_fp8_half.to(self.fp8_dtype)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        input_dtype = x.dtype
        batch_size = x.shape[0]
        seq_len = x.shape[1]

        x_2d = x.view(-1, self.K)

        x_scale = self.compute_scale(x_2d)
        w_scale = self.compute_scale(self.weight)

        x_fp8 = self.quantize_to_fp8(x_2d, x_scale)

        w_t = self.weight.t().contiguous()
        w_fp8 = self.quantize_to_fp8(w_t, w_scale)

        x_scale_inv = (1.0 / x_scale).to(torch.float32)
        w_scale_inv = (1.0 / w_scale).to(torch.float32)

        out = torch._scaled_mm(
            x_fp8,
            w_fp8.t(),
            scale_a=x_scale_inv,
            scale_b=w_scale_inv,
            out_dtype=input_dtype,
        )

        return out.view(batch_size, seq_len, self.N)


