# Optimized quantization kernel
quantize_source = """
#include <hip/hip_runtime.h>
#include <hip/amd_detail/amd_hip_fp16.h>

// Parallel amax reduction kernel
__global__ void compute_amax_kernel(
    const __half* __restrict__ input,
    float* __restrict__ amax_ptr,
    const int size)
{
    extern __shared__ float sdata[];

    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x * 2 + tid;
    int gridSize = blockDim.x * 2 * gridDim.x;

    float myMax = 0.0f;

    while (i < size) {
        __half val1 = input[i];
        float fval1 = __half2float(val1);
        if (fval1 < 0.0f) fval1 = -fval1;
        if (fval1 > myMax) myMax = fval1;

        if (i + blockDim.x < size) {
            __half val2 = input[i + blockDim.x];
            float fval2 = __half2float(val2);
            if (fval2 < 0.0f) fval2 = -fval2;
            if (fval2 > myMax) myMax = fval2;
        }
        i += gridSize;
    }

    sdata[tid] = myMax;
    __syncthreads();

    // reduction
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }

    if (tid == 0) {
        float old = atomicAdd(amax_ptr, 0.0f);
        if (sdata[0] > old) {
            *amax_ptr = sdata[0];
        }
    }
}

torch::Tensor compute_amax_hip(torch::Tensor input) {
    auto size = input.numel();
    torch::Tensor amax = torch::zeros({}, input.options().dtype(torch::kFloat32));

    const int block_size = 256;
    const int num_blocks = min((size + block_size - 1) / block_size, 65536);

    compute_amax_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        (const __half*)input.data_ptr(),
        amax.data_ptr<float>(),
        size
    );

    return amax;
}
"""

quantize_hip = load_inline(
    name="quantize_hip",
    cpp_sources=quantize_source,
    functions=["compute_amax_hip"],
    verbose=True,
    extra_cuda_cflags=["-O3"],
)


class ModelNew(nn.Module):
    """
    Optimized FP8-style Matrix Multiplication with custom HIP kernels.

    Since FP8 is not fully supported, this implementation uses FP16 internally
    but maintains the same mathematical structure as the baseline.
    """
    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        self.quantize_hip = quantize_hip

        # FP8 format specifications (for compatibility)
        if use_e4m3:
            self.fp8_max = 448.0
        else:
            self.fp8_max = 57344.0

        self.weight = nn.Parameter(torch.randn(K, N) * 0.02)

    def compute_scale(self, x: torch.Tensor) -> torch.Tensor:
        """Compute per-tensor scale using custom HIP kernel."""
        amax = self.quantize_hip.compute_amax_hip(x)
        scale = self.fp8_max / amax.clamp(min=1e-12)
        return scale

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Optimized matmul using quantization and standard matmul.
        """
        input_dtype = x.dtype
        batch_size = x.shape[0]
        seq_len = x.shape[1]

        x_2d = x.view(-1, self.K)

        # Compute scales
        x_scale = self.compute_scale(x_2d)
        w_scale = self.compute_scale(self.weight)

        # Quantize to FP8 range (use FP16 for compatibility)
        x_scaled = (x_2d * x_scale).clamp(-self.fp8_max, self.fp8_max)
        w_scaled = (self.weight * w_scale).clamp(-self.fp8_max, self.fp8_max)

        # Perform standard GEMM on quantized values
        out_scaled = x_scaled @ w_scaled

        # Apply inverse scales
        out = out_scaled / (x_scale * w_scale)

        return out.view(batch_size, seq_len, self.N).to(input_dtype)


