class ModelNew(nn.Module):
    """
    Optimized Kimi Delta Attention with fused HIP kernel
    """
    def __init__(
        self,
        hidden_size: int,
        num_heads: int,
        head_dim_qk: int,
        head_dim_v: int,
        use_dplr: bool = False,
        dplr_rank: int = 4,
        use_short_conv: bool = True,
        conv_kernel_size: int = 4,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_heads
        self.head_dim_qk = head_dim_qk
        self.head_dim_v = head_dim_v
        self.use_dplr = use_dplr
        self.dplr_rank = dplr_rank
        self.use_short_conv = use_short_conv

        # Q, K, V projections
        self.q_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)

        # Channel-wise gating
        self.a_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=True)

        # Delta learning rate
        self.b_proj = nn.Linear(hidden_size, num_heads, bias=True)

        # DPLR low-rank factors (optional)
        if use_dplr:
            self.l_proj = nn.Linear(hidden_size, num_heads * dplr_rank, bias=False)
            self.r_proj = nn.Linear(hidden_size, num_heads * dplr_rank, bias=False)

        # Output projection
        self.o_proj = nn.Linear(num_heads * head_dim_v, hidden_size, bias=False)

        # Optional short convolution
        if use_short_conv:
            self.q_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.k_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.v_conv = nn.Conv1d(
                num_heads * head_dim_v, num_heads * head_dim_v,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_v,
                padding=conv_kernel_size - 1
            )

        # Output gate with normalization
        self.g_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)
        self.o_norm = nn.LayerNorm(head_dim_v)

        # Scaling factor for keys
        self.scale = head_dim_qk ** -0.5

        # Custom HIP kernel module
        self.kda_kernel = dapl_kiminet

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Forward pass with optimized HIP kernel.
        """
        batch_size, seq_len, _ = x.shape
        device = x.device
        dtype = x.dtype

        # Project to Q, K, V
        q = self.q_proj(x)  # (batch, seq, num_heads * head_dim_qk)
        k = self.k_proj(x)  # (batch, seq, num_heads * head_dim_qk)
        v = self.v_proj(x)  # (batch, seq, num_heads * head_dim_v)

        # Optional short convolution
        if self.use_short_conv:
            q = self.q_conv(q.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            k = self.k_conv(k.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            v = self.v_conv(v.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            q = F.silu(q)
            k = F.silu(k)
            v = F.silu(v)

        # Reshape for multi-head attention and get tensors
        q = q.view(batch_size, seq_len, self.num_heads, self.head_dim_qk)
        k = k.view(batch_size, seq_len, self.num_heads, self.head_dim_qk)
        v = v.view(batch_size, seq_len, self.num_heads, self.head_dim_v)

        # Channel-wise gating
        a = torch.sigmoid(self.a_proj(x))
        a = a.view(batch_size, seq_len, self.num_heads, self.head_dim_v)

        # Delta learning rate
        beta = torch.sigmoid(self.b_proj(x))

        # Scale keys
        k = k * self.scale

        # Initialize state matrix
        S = torch.zeros(
            batch_size, self.num_heads, self.head_dim_v, self.head_dim_qk,
            device=device, dtype=dtype
        )

        # Initialize output tensor (will accumulate results)
        output = torch.zeros(
            batch_size, seq_len, self.num_heads, self.head_dim_v,
            device=device, dtype=dtype
        )

        # Get contiguous versions for kernel
        S = S.contiguous()
        k = k.contiguous()
        q = q.contiguous()
        v = v.contiguous()
        a = a.contiguous()
        beta = beta.contiguous()
        output = output.contiguous()

        # Launch fused kernel
        self.kda_kernel.kda_state_update_kernel(
            S, k, q, v, a, beta, output,
            batch_size, self.num_heads, seq_len,
            self.head_dim_v, self.head_dim_qk
        )

        # Apply output normalization per head
        o = self.o_norm(output)

        # Apply output gate
        g = torch.sigmoid(self.g_proj(x))
        g = g.view(batch_size, seq_len, self.num_heads, self.head_dim_v)
        o = o * g

        # Reshape and project output
        o = o.reshape(batch_size, seq_len, self.num_heads * self.head_dim_v)
        o = self.o_proj(o)

        return o

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused attention kernel with masked softmax
attention_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void fused_attention_kernel(
    const float* __restrict__ query,
    const float* __restrict__ key,
    const float* __restrict__ value,
    float* __restrict__ output,
    int batch_size,
    int num_heads,
    int seq_len,
    int head_dim,
    float softmax_scale
) {
    int b = blockIdx.x;
    int h = blockIdx.y;

    if (b >= batch_size || h >= num_heads) return;

    int out_base = ((b * num_heads + h) * seq_len) * head_dim;

    // Process each query position
    for (int t = threadIdx.x; t < seq_len; t += blockDim.x) {
        int q_base = ((b * num_heads + h) * seq_len + t) * head_dim;

        // Compute attention scores for this query position
        float scores[2048];  // Max seq_len

        for (int i = 0; i < seq_len; i++) {
            int k_base = ((b * num_heads + h) * seq_len + i) * head_dim;

            // Dot product
            float dot = 0.0f;
            for (int d = 0; d < head_dim; d++) {
                dot += query[q_base + d] * key[k_base + d];
            }

            // Apply causal mask (only pay attention to positions <= current)
            scores[i] = (i <= t) ? dot * softmax_scale : -1e10f;
        }

        // Compute softmax
        float max_score = -1e10f;
        for (int i = 0; i <= t; i++) {
            max_score = fmaxf(max_score, scores[i]);
        }

        float sum = 0.0f;
        for (int i = 0; i <= t; i++) {
            scores[i] = expf(scores[i] - max_score);
            sum += scores[i];
        }

        // Normalize
        for (int i = 0; i <= t; i++) {
            scores[i] /= sum;
        }

        // Apply attention to value
        for (int d = 0; d < head_dim; d++) {
            float accum = 0.0f;
            for (int i = 0; i <= t; i++) {
                int v_base = ((b * num_heads + h) * seq_len + i) * head_dim;
                accum += scores[i] * value[v_base + d];
            }
            output[out_base + t * head_dim + d] = accum;
        }
    }
}

torch::Tensor fused_attention_hip(
    torch::Tensor query, torch::Tensor key, torch::Tensor value, float softmax_scale
) {
    auto batch_size = query.size(0);
    auto num_heads = query.size(1);
    auto seq_len = query.size(2);
    auto head_dim = query.size(3);

    auto output = torch::empty({batch_size, num_heads, seq_len, head_dim}, 
                               query.options());

    dim3 grid(batch_size, num_heads);
    int block_size = 256;

    fused_attention_kernel<<<grid, block_size>>>(
        query.data_ptr<float>(),
        key.data_ptr<float>(),
        value.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_heads,
        seq_len,
        head_dim,
        softmax_scale
    );

    return output;
}
"""

attention = load_inline(
    name="attention",
    cpp_sources=attention_cpp_source,
    functions=["fused_attention_hip"],
    verbose=False,
)


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
    cos = cos.unsqueeze(unsqueeze_dim)
    sin = sin.unsqueeze(unsqueeze_dim)
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


class DeepSeekRMSNorm(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)


class DeepSeekRotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=2048, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos(), emb.sin()


class ModelNew(nn.Module):
    """
    Optimized DeepSeek-V3 Multi-head Latent Attention (MLA)

    Key optimizations:
    1. Fused attention kernel with masked softmax
    """

    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        q_lora_rank: int,
        kv_lora_rank: int,
        qk_nope_head_dim: int,
        qk_rope_head_dim: int,
        v_head_dim: int,
        max_position_embeddings: int = 2048,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.q_lora_rank = q_lora_rank
        self.kv_lora_rank = kv_lora_rank
        self.qk_nope_head_dim = qk_nope_head_dim
        self.qk_rope_head_dim = qk_rope_head_dim
        self.v_head_dim = v_head_dim
        self.q_head_dim = qk_nope_head_dim + qk_rope_head_dim
        self.attention_dropout = attention_dropout
        self.softmax_scale = self.q_head_dim ** (-0.5)

        # Query projection with LoRA compression
        self.q_a_proj = nn.Linear(hidden_size, q_lora_rank, bias=False)
        self.q_a_layernorm = DeepSeekRMSNorm(q_lora_rank)
        self.q_b_proj = nn.Linear(q_lora_rank, num_attention_heads * self.q_head_dim, bias=False)

        # KV projection with LoRA compression (MQA-style: shared across heads initially)
        self.kv_a_proj_with_mqa = nn.Linear(
            hidden_size, kv_lora_rank + qk_rope_head_dim, bias=False
        )
        self.kv_a_layernorm = DeepSeekRMSNorm(kv_lora_rank)
        self.kv_b_proj = nn.Linear(
            kv_lora_rank,
            num_attention_heads * (qk_nope_head_dim + v_head_dim),
            bias=False,
        )

        # Output projection
        self.o_proj = nn.Linear(num_attention_heads * v_head_dim, hidden_size, bias=False)

        # Rotary embeddings
        self.rotary_emb = DeepSeekRotaryEmbedding(
            qk_rope_head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

        # Load fused attention kernel
        self.fused_attention_hip = attention.fused_attention_hip

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        # Query projection with LoRA compression
        q = self.q_b_proj(self.q_a_layernorm(self.q_a_proj(hidden_states)))
        q = q.view(bsz, q_len, self.num_heads, self.q_head_dim).transpose(1, 2)

        # Split query into nope (non-positional) and rope (positional) components
        q_nope, q_pe = torch.split(q, [self.qk_nope_head_dim, self.qk_rope_head_dim], dim=-1)

        # KV projection with compression
        compressed_kv = self.kv_a_proj_with_mqa(hidden_states)
        compressed_kv, k_pe = torch.split(
            compressed_kv, [self.kv_lora_rank, self.qk_rope_head_dim], dim=-1
        )
        k_pe = k_pe.view(bsz, q_len, 1, self.qk_rope_head_dim).transpose(1, 2)

        # Expand compressed KV
        kv = self.kv_b_proj(self.kv_a_layernorm(compressed_kv))
        kv = kv.view(bsz, q_len, self.num_heads, self.qk_nope_head_dim + self.v_head_dim)
        kv = kv.transpose(1, 2)

        k_nope, value_states = torch.split(kv, [self.qk_nope_head_dim, self.v_head_dim], dim=-1)

        # Apply rotary embeddings to positional components only
        cos, sin = self.rotary_emb(value_states, seq_len=q_len)
        # cos, sin are (q_len, qk_rope_head_dim)
        # Need to broadcast properly for q_pe (bsz, num_heads, q_len, qk_rope_head_dim)
        cos_squeezed = cos.unsqueeze(0)  # (1, q_len, qk_rope_head_dim)
        cos_squeezed = cos_squeezed.unsqueeze(0)  # (1, 1, q_len, qk_rope_head_dim) for broadcasting
        sin_squeezed = sin.unsqueeze(0)
        sin_squeezed = sin_squeezed.unsqueeze(0)

        # For q_pe, we need to broadcast cos/sin to match (bsz, num_heads, q_len, qk_rope_head_dim)
        cos_for_q = cos.unsqueeze(0).unsqueeze(0)  # (1, 1, q_len, qk_rope_head_dim)
        sin_for_q = sin.unsqueeze(0).unsqueeze(0)

        q_embed = (q_pe * cos_for_q) + (rotate_half(q_pe) * sin_for_q)
        k_embed = (k_pe * cos_for_q) + (rotate_half(k_pe) * sin_for_q)

        q_pe = q_embed
        k_pe = k_embed

        # Assemble full query and key states
        query_states = torch.empty(bsz, self.num_heads, q_len, self.q_head_dim,
                                   device=hidden_states.device, dtype=hidden_states.dtype)
        query_states[:, :, :, :self.qk_nope_head_dim] = q_nope
        query_states[:, :, :, self.qk_nope_head_dim:] = q_pe

        key_states = torch.empty(bsz, self.num_heads, q_len, self.q_head_dim,
                                 device=hidden_states.device, dtype=hidden_states.dtype)
        key_states[:, :, :, :self.qk_nope_head_dim] = k_nope
        key_states[:, :, :, self.qk_nope_head_dim:] = k_pe

        # Compute attention using fused kernel
        attn_output = self.fused_attention_hip(query_states, key_states, value_states, self.softmax_scale)

        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.v_head_dim)
        attn_output = self.o_proj(attn_output)

        return attn_output

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused GQA attention kernel that avoids explicit KV head expansion
gqa_attention_hip_source = r"""
#include <hip/hip_runtime.h>
#include <math.h>

#define WARP_SIZE 32

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_xor(val, offset);
    }
    return val;
}

__global__ void gqa_attention_fused_kernel(
    const float* __restrict__ q,        // [batch, num_heads, seq_len, head_dim]
    const float* __restrict__ k,        // [batch, num_kv_heads, seq_len, head_dim]
    const float* __restrict__ v,        // [batch, num_kv_heads, seq_len, head_dim]
    float* __restrict__ output,         // [batch, num_heads, seq_len, head_dim]
    float softmax_scale,
    int batch_size,
    int num_heads,
    int num_kv_heads,
    int seq_len,
    int head_dim,
    int key_value_groups
) {
    // Each block handles one query head and one query position
    const int batch_idx = blockIdx.z;
    const int q_head_idx = blockIdx.y;
    const int q_pos = blockIdx.x;

    // Compute corresponding KV head (multiple query heads share same KV head)
    const int kv_head_idx = q_head_idx / key_value_groups;

    // Causal mask: only compute for positions <= q_pos
    const int kv_seq_len = min(q_pos + 1, seq_len);

    // Lane ID in warp
    const int lane_id = threadIdx.x;

    // Check bounds
    if (batch_idx >= batch_size || q_head_idx >= num_heads || q_pos >= seq_len) {
        return;
    }

    // Base indices for q, k, v
    const int q_base = ((long long)batch_idx * num_heads + q_head_idx) * seq_len * head_dim + q_pos * head_dim;
    const int kv_base = ((long long)batch_idx * num_kv_heads + kv_head_idx) * seq_len * head_dim;

    // Shared memory for attention weights and buffer
    extern __shared__ float s_mem[];
    float* w_sh = s_mem;
    float* q_vec_sh = s_mem + seq_len;

    // Load query vector into shared memory (all threads cooperatively load)
    for (int i = lane_id; i < head_dim; i += WARP_SIZE) {
        q_vec_sh[i] = q[q_base + i];
    }

    __syncthreads();

    // 2. Compute QK^T for each key position (each thread handles some positions)
    for (int kv_pos = lane_id; kv_pos < kv_seq_len; kv_pos += WARP_SIZE) {
        // Compute dot product between query and this key vector
        float sum_qk = 0.0f;
        int k_base = kv_base + kv_pos * head_dim;

        for (int i = 0; i < head_dim; i++) {
            sum_qk += q_vec_sh[i] * k[k_base + i];
        }

        // Store in shared memory
        w_sh[kv_pos] = sum_qk * softmax_scale;
    }

    __syncthreads();

    // 3. Softmax - compute max
    float my_max = -INFINITY;
    for (int i = lane_id; i < kv_seq_len; i += WARP_SIZE) {
        my_max = fmaxf(my_max, w_sh[i]);
    }

    // Reduce max across warp
    for (int offset = 16; offset > 0; offset /= 2) {
        my_max = fmaxf(my_max, __shfl_xor(my_max, offset));
    }
    float max_val = __shfl(my_max, 0);

    // 4. Compute exp and sum
    float my_exp_sum = 0.0f;
    for (int i = lane_id; i < kv_seq_len; i += WARP_SIZE) {
        float exp_val = expf(w_sh[i] - max_val);
        w_sh[i] = exp_val;
        my_exp_sum += exp_val;
    }

    // Reduce sum across warp
    for (int offset = 16; offset > 0; offset /= 2) {
        my_exp_sum += __shfl_xor(my_exp_sum, offset);
    }
    float exp_sum = fmaxf(my_exp_sum, 1e-6f);

    // 5. Normalize
    for (int i = lane_id; i < kv_seq_len; i += WARP_SIZE) {
        w_sh[i] = w_sh[i] / exp_sum;
    }

    __syncthreads();

    // 6. Compute weighted sum over V vectors (each thread computes one output element)
    int out_base = ((long long)batch_idx * num_heads + q_head_idx) * seq_len * head_dim + q_pos * head_dim;

    if (lane_id < head_dim) {
        float out_val = 0.0f;
        for (int kv_pos = 0; kv_pos < kv_seq_len; kv_pos++) {
            int v_base = kv_base + kv_pos * head_dim;
            float v_val = v[v_base + lane_id];
            out_val += w_sh[kv_pos] * v_val;
        }
        output[out_base + lane_id] = out_val;
    }
}

torch::Tensor gqa_attention_forward(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    float softmax_scale,
    int key_value_groups
) {
    auto batch_size = q.size(0);
    auto num_heads = q.size(1);
    auto num_kv_heads = k.size(1);
    auto seq_len = q.size(2);
    auto head_dim = q.size(3);

    auto output = torch::empty_like(q);

    const int block_size = 32;  // One warp per block
    dim3 grid(seq_len, num_heads, batch_size);

    int shared_mem_size = (seq_len + head_dim) * sizeof(float);

    hipLaunchKernelGGL(
        (gqa_attention_fused_kernel),
        grid, dim3(block_size, 1, 1), shared_mem_size, 0,
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        output.data_ptr<float>(),
        softmax_scale,
        (int)batch_size,
        (int)num_heads,
        (int)num_kv_heads,
        (int)seq_len,
        (int)head_dim,
        (int)key_value_groups
    );

    return output;
}
"""

# Load the fused attention kernel
gqa_attention = load_inline(
