import os
import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

dapl_kiminet_hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <torch/extension.h>
#include <hip/hip_runtime_api.h>

// Optimized kernel using warp-level primitives for synchronization
__global__ void kda_state_update_kernel_device(
    float* S,
    const float* k,
    const float* q,
    const float* v,
    const float* a,
    const float* beta,
    float* output,
    int batch_size,
    int num_heads,
    int seq_len,
    int head_dim_v,
    int head_dim_qk
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;

    int total_elements = batch_size * num_heads * head_dim_v * head_dim_qk;
    if (tid >= total_elements) return;

    // Decompose tid
    int temp = tid;
    int j = temp % head_dim_qk;
    temp /= head_dim_qk;
    int i = temp % head_dim_v;
    temp /= head_dim_v;
    int h = temp % num_heads;
    int b = temp / num_heads;

    int S_base = b * num_heads * head_dim_v * head_dim_qk +
                 h * head_dim_v * head_dim_qk +
                 i * head_dim_qk + j;

    float S_ij = S[S_base];

    for (int t = 0; t < seq_len; t++) {
        // Compute (S @ k)[i] using shared memory or registers
        // Since we're in a warp, we can use warp-based reductions

        // Broadcast k_t values and compute partial dot product
        float S_k = 0.0f;
        int k_idx_base = b * seq_len * num_heads * head_dim_qk +
                        t * num_heads * head_dim_qk +
                        h * head_dim_qk;
        int S_row_base = b * num_heads * head_dim_v * head_dim_qk +
                        h * head_dim_v * head_dim_qk +
                        i * head_dim_qk;

        // Each thread computes contribution at its j position
        float k_td = k[k_idx_base + j];
        float S_ij_local = S[S_row_base + j];
        S_k = S_ik_local * k_td;

        // Warp reduction to sum across all j in the warp
        // Use reduction across threads that share the same (b, h, i)
        // Since each (j) maps to different threads in same group

        // Get lane ID
        int lane_id = threadIdx.x % 32;

        // Use warp shuffle to sum contributions
        // This works if threads with same (b,h,i) are in same warp
        // But we need to ensure this property via thread mapping

        // For now, use simple shared memory reduction
        __shared__ float warp_shmem[32];
        int warp_id = threadIdx.x / 32;

        // Store reduction in shared memory
        float warp_sum = S_k;
        for (int offset = 16; offset > 0; offset /= 2) {
            warp_sum += __shfl_xor(warp_sum, offset, 32);
        }

        // Thread 0 in each warp writes the sum
        if (lane_id == 0) {
            warp_shmem[warp_id] = warp_sum;
        }
        __syncthreads();

        // Now all threads with same (b,h,i) should have same S_k value
        // Actually, we need to be careful about which threads have same (b,h,i)

        // SIMPLIFIED APPROACH: Just compute S_k by reading row from S directly
        // For each thread (b,h,i,j), S_k should be the same value
        // But we need to ensure we read consistent S values

        // Let's use a different approach: read into shared memory first
        __shared__ float row_snapshot[256 + 32];  // +32 for padding

        // Each thread loads its S[i,j] value
        if (j < 128) {  // Assuming head_dim_qk <= 128
            row_snapshot[j] = S[S_row_base + j];
        }
        __syncthreads();

        // Now compute S_k from shared memory (this should be consistent)
        S_k = 0.0f;
        for (int kd = 0; kd < head_dim_qk; kd++) {
            S_k += row_snapshot[kd] * k[k_idx_base + kd];
        }

        // Read v_t[i]
        int v_idx = b * seq_len * num_heads * head_dim_v +
                   t * num_heads * head_dim_v +
                   h * head_dim_v +
                   i;
        float v_ti = v[v_idx];

        // Error
        float error = S_k - v_ti;

        // Read beta_t
        int beta_idx = b * seq_len * num_heads + t * num_heads + h;
        float beta_t = beta[beta_idx];
        float k_tj = k[k_idx_base + j];

        // Delta
        float delta = -beta_t * error * k_tj;

        // Read a_t[i]
        int a_idx = b * seq_len * num_heads * head_dim_v +
                    t * num_heads * head_dim_v +
                    h * head_dim_v +
                    i;
        float a_ti = a[a_idx];

        // Update S (use OLD S_ij, not the value from shared memory!)
        S_ij = a_ti * S_ij + delta;
        S[S_base] = S_ij;

        // Output accumulation
        int q_idx_base = b * seq_len * num_heads * head_dim_qk +
                        t * num_heads * head_dim_qk +
                        h * head_dim_qk;
        float q_tj = q[q_idx_base + j];

        int output_idx = b * seq_len * num_heads * head_dim_v +
                        t * num_heads * head_dim_v +
                        h * head_dim_v +
                        i;
        atomicAdd(&output[output_idx], S_ij * q_tj);
    }
}

torch::Tensor kda_state_update_kernel(
    torch::Tensor S,
    torch::Tensor k,
    torch::Tensor q,
    torch::Tensor v,
    torch::Tensor a,
    torch::Tensor beta,
    torch::Tensor output,
    int64_t batch_size,
    int64_t num_heads,
    int64_t seq_len,
    int64_t head_dim_v,
    int64_t head_dim_qk
) {
    const int block_size = 256;
    int64_t total_elements = batch_size * num_heads * head_dim_v * head_dim_qk;
    int64_t num_blocks = (total_elements + block_size - 1) / block_size;
    int shared_mem_size = (block_size + 32) * sizeof(float);

    kda_state_update_kernel_device<<<num_blocks, block_size, shared_mem_size>>>(
        S.data_ptr<float>(),
        k.data_ptr<float>(),
        q.data_ptr<float>(),
        v.data_ptr<float>(),
        a.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_heads,
        seq_len,
        head_dim_v,
        head_dim_qk
    );

    return output;
}
"""

dapl_kiminet = load_inline(
    name="dapl_kiminet",
    cpp_sources=dapl_kiminet_hip_source,
    functions=["kda_state_update_kernel"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized Kimi Delta Attention with fused HIP kernel
    """
    def __init__(
        self,
        hidden_size: int,
        num_heads: int,
        head_dim_qk: int,
        head_dim_v: int,
        use_dplr: bool = False,
        dplr_rank: int = 4,
        use_short_conv: bool = True,
        conv_kernel_size: int = 4,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_heads
        self.head_dim_qk = head_dim_qk
        self.head_dim_v = head_dim_v
        self.use_dplr = use_dplr
        self.dplr_rank = dplr_rank
        self.use_short_conv = use_short_conv

        # Q, K, V projections
        self.q_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)

        # Channel-wise gating
        self.a_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=True)

        # Delta learning rate
        self.b_proj = nn.Linear(hidden_size, num_heads, bias=True)

        # DPLR low-rank factors (optional)
        if use_dplr:
            self.l_proj = nn.Linear(hidden_size, num_heads * dplr_rank, bias=False)
            self.r_proj = nn.Linear(hidden_size, num_heads * dplr_rank, bias=False)

        # Output projection
        self.o_proj = nn.Linear(num_heads * head_dim_v, hidden_size, bias=False)

        # Optional short convolution
        if use_short_conv:
            self.q_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.k_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.v_conv = nn.Conv1d(
                num_heads * head_dim_v, num_heads * head_dim_v,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_v,
                padding=conv_kernel_size - 1
            )

        # Output gate with normalization
        self.g_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)
        self.o_norm = nn.LayerNorm(head_dim_v)

        # Scaling factor for keys
        self.scale = head_dim_qk ** -0.5

        # Custom HIP kernel module
        self.kda_kernel = dapl_kiminet

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Forward pass with optimized HIP kernel.
        """
        batch_size, seq_len, _ = x.shape
        device = x.device
        dtype = x.dtype

        # Project to Q, K, V
        q = self.q_proj(x)  # (batch, seq, num_heads * head_dim_qk)
        k = self.k_proj(x)  # (batch, seq, num_heads * head_dim_qk)
        v = self.v_proj(x)  # (batch, seq, num_heads * head_dim_v)

        # Optional short convolution
        if self.use_short_conv:
            q = self.q_conv(q.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            k = self.k_conv(k.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            v = self.v_conv(v.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            q = F.silu(q)
            k = F.silu(k)
            v = F.silu(v)

        # Reshape for multi-head attention and get tensors
        q = q.view(batch_size, seq_len, self.num_heads, self.head_dim_qk)
        k = k.view(batch_size, seq_len, self.num_heads, self.head_dim_qk)
        v = v.view(batch_size, seq_len, self.num_heads, self.head_dim_v)

        # Channel-wise gating
        a = torch.sigmoid(self.a_proj(x))
        a = a.view(batch_size, seq_len, self.num_heads, self.head_dim_v)

        # Delta learning rate
        beta = torch.sigmoid(self.b_proj(x))

        # Scale keys
        k = k * self.scale

        # Initialize state matrix
        S = torch.zeros(
            batch_size, self.num_heads, self.head_dim_v, self.head_dim_qk,
            device=device, dtype=dtype
        )

        # Initialize output tensor (will accumulate results)
        output = torch.zeros(
            batch_size, seq_len, self.num_heads, self.head_dim_v,
            device=device, dtype=dtype
        )

        # Get contiguous versions for kernel
        S = S.contiguous()
        k = k.contiguous()
        q = q.contiguous()
        v = v.contiguous()
        a = a.contiguous()
        beta = beta.contiguous()
        output = output.contiguous()

        # Launch fused kernel
        self.kda_kernel.kda_state_update_kernel(
            S, k, q, v, a, beta, output,
            batch_size, self.num_heads, seq_len,
            self.head_dim_v, self.head_dim_qk
        )

        # Apply output normalization per head
        o = self.o_norm(output)

        # Apply output gate
        g = torch.sigmoid(self.g_proj(x))
        g = g.view(batch_size, seq_len, self.num_heads, self.head_dim_v)
        o = o * g

        # Reshape and project output
        o = o.reshape(batch_size, seq_len, self.num_heads * self.head_dim_v)
        o = self.o_proj(o)

        return o

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused GQA attention kernel that avoids explicit KV head expansion
gqa_attention_hip_source = r"""
#include <hip/hip_runtime.h>
#include <math.h>

#define WARP_SIZE 32
#define MAX_SEQ_LEN 2048
#define MAX_HEAD_DIM 128

__global__ void gqa_attention_fused_kernel(
    const float* __restrict__ q,        // [batch, num_heads, seq_len, head_dim]
    const float* __restrict__ k,        // [batch, num_kv_heads, seq_len, head_dim]
    const float* __restrict__ v,        // [batch, num_kv_heads, seq_len, head_dim]
    float* __restrict__ output,         // [batch, num_heads, seq_len, head_dim]
    float softmax_scale,
    int batch_size,
    int num_heads,
    int num_kv_heads,
    int seq_len,
    int head_dim,
    int key_value_groups
) {
    // Each block handles one query head and one query position
    const int batch_idx = blockIdx.z;
    const int q_head_idx = blockIdx.y;
    const int q_pos = blockIdx.x;

    // Compute corresponding KV head (multiple query heads share same KV head)
    const int kv_head_idx = q_head_idx / key_value_groups;

    // Causal mask: only compute for positions <= q_pos
    const int kv_seq_len = min(q_pos + 1, seq_len);

    // Lane ID in warp
    const int lane_id = threadIdx.x;

    // Check bounds
    if (batch_idx >= batch_size || q_head_idx >= num_heads || q_pos >= seq_len) {
        return;
    }

    // Base index for query vector
    const int q_base = ((long long)batch_idx * num_heads + q_head_idx) * seq_len * head_dim + q_pos * head_dim;

    // Base index for KV
    const int kv_base = ((long long)batch_idx * num_kv_heads + kv_head_idx) * seq_len * head_dim;

    // Shared memory: attention weights + query vector
    __shared__ float w_sh[MAX_SEQ_LEN];
    __shared__ float q_vec_sh[MAX_HEAD_DIM];

    // Initialize w_sh to 0
    for (int i = lane_id; i < kv_seq_len; i += WARP_SIZE) {
        w_sh[i] = 0.0f;
    }
    __syncthreads();

    // Load query vector into shared memory (all threads cooperatively load)
    for (int i = lane_id; i < head_dim; i += WARP_SIZE) {
        q_vec_sh[i] = q[q_base + i];
    }
    __syncthreads();

    // Compute QK^T for each key position
    for (int kv_pos = lane_id; kv_pos < kv_seq_len; kv_pos += WARP_SIZE) {
        int k_base = kv_base + kv_pos * head_dim;

        // Compute dot product between query and this key vector
        float sum_qk = 0.0f;
        for (int i = 0; i < head_dim; i++) {
            sum_qk += q_vec_sh[i] * k[k_base + i];
        }

        // Add to shared memory
        atomicAdd(&w_sh[kv_pos], sum_qk * softmax_scale);
    }
    __syncthreads();

    // Softmax - compute max
    float my_max = -INFINITY;
    for (int i = lane_id; i < kv_seq_len; i += WARP_SIZE) {
        my_max = fmaxf(my_max, w_sh[i]);
    }

    // Reduce max across warp
    for (int offset = 16; offset > 0; offset /= 2) {
        my_max = fmaxf(my_max, __shfl_xor(my_max, offset));
    }
    float max_val = __shfl(my_max, 0);

    // Compute exp and sum
    float my_exp_sum = 0.0f;
    for (int i = lane_id; i < kv_seq_len; i += WARP_SIZE) {
        float exp_val = expf(w_sh[i] - max_val);
        w_sh[i] = exp_val;
        my_exp_sum += exp_val;
    }

    // Reduce sum across warp
    for (int offset = 16; offset > 0; offset /= 2) {
        my_exp_sum += __shfl_xor(my_exp_sum, offset);
    }
    float exp_sum = fmaxf(my_exp_sum, 1e-6f);

    // Normalize (each thread handles its own position)
    for (int i = lane_id; i < kv_seq_len; i += WARP_SIZE) {
        w_sh[i] = w_sh[i] / exp_sum;
    }

    __syncthreads();

    // Compute weighted sum over V (only threads 0..head_dim-1 participate)
    if (lane_id < head_dim) {
        float out_val = 0.0f;
        for (int kv_pos = 0; kv_pos < kv_seq_len; kv_pos++) {
            int v_base = kv_base + kv_pos * head_dim;
            float v_val = v[v_base + lane_id];
            out_val += w_sh[kv_pos] * v_val;
        }

        // Write output
        output[q_base + lane_id] = out_val;
    }
}

torch::Tensor gqa_attention_forward(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    float softmax_scale,
    int key_value_groups
) {
    auto batch_size = q.size(0);
    auto num_heads = q.size(1);
    auto num_kv_heads = k.size(1);
    auto seq_len = q.size(2);
    auto head_dim = q.size(3);

    auto output = torch::empty_like(q);

    const int block_size = 32;  // One warp per block
    dim3 grid(seq_len, num_heads, batch_size);

    hipLaunchKernelGGL(
        (gqa_attention_fused_kernel),
        grid, dim3(block_size, 1, 1), 0, 0,
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        output.data_ptr<float>(),
        softmax_scale,
        (int)batch_size,
        (int)num_heads,
        (int)num_kv_heads,
        (int)seq_len,
        (int)head_dim,
        (int)key_value_groups
    );

    return output;
}
"""

# Load the fused attention kernel
gqa_attention = load_inline(
    name="gqa_attention",
    cpp_sources=gqa_attention_hip_source,
    functions=["gqa_attention_forward"],
    extra_cflags=["-O3", "-ffast-math"],
    verbose=False,
)


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(q, k, cos, sin):
    """Apply rotary positional embeddings."""
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos().unsqueeze(0).unsqueeze(0), emb.sin().unsqueeze(0).unsqueeze(0)


class ModelNew(nn.Module):
    """
    Grouped Query Attention (GQA) - Optimized with Fused Kernel

    Optimizations:
    1. Replaced standard matmul attention with fused GQA kernel
    2. Avoids explicit KV head expansion (computes implicitly)
    3. Fuses dot product, softmax, and value aggregation in single kernel
    4. Reduces memory traffic by eliminating temporary KV expansion
    """

    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        max_position_embeddings: int = 4096,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.num_kv_heads = num_key_value_heads
        self.head_dim = head_dim
        self.num_key_value_groups = num_attention_heads // num_key_value_heads
        self.attention_dropout = attention_dropout
        self.softmax_scale = head_dim ** (-0.5)

        # Separate projections for Q, K, V
        self.q_proj = nn.Linear(hidden_size, num_attention_heads * head_dim, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.o_proj = nn.Linear(num_attention_heads * head_dim, hidden_size, bias=False)

        # Rotary embeddings
        self.rotary_emb = RotaryEmbedding(
            head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

        # Custom fused attention kernel
        self.gqa_kernel = gqa_attention

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        # Project Q, K, V
        query_states = self.q_proj(hidden_states)
        key_states = self.k_proj(hidden_states)
        value_states = self.v_proj(hidden_states)

        # Reshape for multi-head attention
        query_states = query_states.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2)
        key_states = key_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)
        value_states = value_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)

        # Apply rotary embeddings
        cos, sin = self.rotary_emb(value_states, seq_len=q_len)
        query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        # Compute attention with fused GQA kernel
        # This avoids explicit KV head expansion
        attn_output = self.gqa_kernel.gqa_attention_forward(
            query_states,
            key_states,
            value_states,
            self.softmax_scale,
            self.num_key_value_groups
        )

        # Apply dropout
        if self.attention_dropout > 0.0 and self.training:
            attn_output = F.dropout(attn_output, p=self.attention_dropout, training=True)

        # Reshape and output projection
        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.head_dim)
        attn_output = self.o_proj(attn_output)

        return attn_output

